'use strict';
let defaultAiStatus={configured:false,checked:false,model:''};
async function refreshDefaultAiStatus(){try{const r=await fetch('/api/openai/status',{credentials:'same-origin',cache:'no-store',redirect:'error'});if(r.ok){const d=await r.json();defaultAiStatus={configured:d.configured===true,checked:true,model:String(d.model||'')};}}catch{}if(screen==='coach')render(true);}
async function kaincheckAiRequest(path,body,signal){const r=await fetch('/api/openai/'+path,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal,redirect:'error'});let data;try{data=await r.json();}catch{throw Error('Could not read the AI response.');}if(!r.ok)throw Error(data.error?.message||'The AI request failed.');return data;}
async function builtinOpenAiReply(input,signal,history=state.messages){const c=state.coach;const data=await kaincheckAiRequest('coach',{coach:{id:c.templateId||state.activeBuiltinId||'kai',name:c.name,tone:c.tone,language:c.language,length:c.length,vibe:c.vibe,instructions:c.instructions},messages:history.filter(m=>!m.error).slice(-28).map(m=>({role:m.role==='user'?'user':'assistant',content:String(m.text||'').slice(0,6000)})),context:{username:state.name,budget:state.budget,minutes:state.time,movement:state.preferred,meals:state.meals,...wellnessCoachContext()}},signal);return {...parseLiveReply(data.text),source:'openai'};}
async function customOpenAiReply(c,signal,history=state.messages){const config=normalizeConnection(c.connection);const messages=conversationContext(c,history,1024).filter(m=>m.role!=='system').slice(-32).map(m=>({...m,content:m.content.slice(0,6000)}));if(!messages.length)throw Error('Add a message before asking your coach.');const data=await kaincheckAiRequest('coach',{coach:{type:'custom',name:c.name,customPrompt:customPromptValue(c),character:normalizeCharacter(c.character)},generation:{maxTokens:config.maxTokens},messages,context:{username:state.name,budget:state.budget,minutes:state.time,movement:state.preferred,meals:state.meals,...wellnessCoachContext()}},signal);return {...parseLiveReply(data.text),source:'openai'};}
